                        ins_i = dist[prev_i][b] + dist[b][next_i] - dist[prev_i][next_i]
                        ins_j = dist[prev_j][a] + dist[a][next_j] - dist[prev_j][next_j]
                        delta = rem_i + rem_j + ins_i + ins_j
                        if delta < -1e-12 and (best is None or delta < best[0]):
                            best = (delta, p, q)
                if best is not None:
                    _, p, q = best
                    a = ri[p]
                    b = rj[q]
                    ri[p], rj[q] = b, a
                    changed = True
                    break

        routes = [r for r in routes if r]

    # Final deterministic cleanup: ensure all customers appear exactly once.
    seen = {}
    for r in routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1

    missing = []
    for c in customers:
        if seen.get(c, 0) == 0:
            missing.append(c)

    if missing:
        # Add missing customers to routes with best feasible insertion; otherwise new route.
        for node in missing:
            best = None
            best_r = None
            best_p = None
            for ri, r in enumerate(routes):
                if route_load(r) + demands[node] > capacity:
                    continue
                for p in range(len(r) + 1):
                    delta = feasible_insert_cost(r, p, node)
                    if best is None or delta < best:
                        best = delta
                        best_r = ri
                        best_p = p
            if best_r is None:
                routes.append([node])
            else:
                routes[best_r].insert(best_p, node)

    # Remove duplicates if any by keeping first occurrence and reassigning extras.
    used = set()
    cleaned = []
    extras = []
    for r in routes:
        nr = []
        for c in r:
            if c not in used:
                used.add(c)
                nr.append(c)
            else:
                extras.append(c)
        if nr:
            cleaned.append(nr)
    routes = cleaned
    if extras:
        for c in extras:
            best = None
            best_r = None
            best_p = None
            for ri, r in enumerate(routes):
                if route_load(r) + demands[c] > capacity:
                    continue
                for p in range(len(r) + 1):
                    delta = feasible_insert_cost(r, p, c)
                    if best is None or delta < best:
                        best = delta
                        best_r = ri
                        best_p = p
            if best_r is None:
                routes.append([c])
            else:
                routes[best_r].insert(best_p, c)

    return routes
